export type EntityType = 'star' | 'planet' | 'moon' | 'constellation';
export type PlanetBody = 'mercury' | 'venus' | 'mars' | 'jupiter' | 'saturn' | 'uranus' | 'neptune';

export interface EntityFact {
  readonly label: string;
  readonly value: string;
}

interface EntityBase {
  /** Dictionary key. */
  readonly id: string;
  readonly name: string;
  /** Short line shown beside the type, e.g. "Red supergiant". */
  readonly subtitle: string;
  readonly description: string;
  readonly facts: readonly EntityFact[];
  /** Label level of detail: the name is hidden while the field of view (degrees) is at or above this. */
  readonly labelMaxFov: number;
}

export interface StarDetail extends EntityBase {
  readonly type: 'star';
  /** A catalog star by Hipparcos number, or the Sun. */
  readonly anchor: { readonly hip: number } | { readonly body: 'sun' };
}

export interface PlanetDetail extends EntityBase {
  readonly type: 'planet';
  readonly body: PlanetBody;
}

export interface MoonDetail extends EntityBase {
  readonly type: 'moon';
}

export interface ConstellationDetail extends EntityBase {
  readonly type: 'constellation';
  /**
   * Hipparcos numbers of stars on the figure's lines. The figure is every line connected to a seed, so
   * a figure drawn as separate pieces (Crux) needs one seed per piece, and neighbors that share a star
   * on the line data (Taurus and Auriga) would merge.
   */
  readonly seedStars: readonly number[];
}

export type EntityDetail = StarDetail | PlanetDetail | MoonDetail | ConstellationDetail;

